const ATOMS = 'Wayfarer · Atoms'; // added
const LAYOUT = 'Wayfarer · Layout'; // added

const space = (displayName: string, defaultValue: string) => ({
  type: 'choice' as const,
  displayName,
  options: [
    { label: 'None', value: 'none' },
    { label: 'Small', value: 'small' },
    { label: 'Medium', value: 'medium' },
    { label: 'Large', value: 'large' },
  ],
  defaultValue: [defaultValue],
});

/** An empty Area: what Studio adds when an author raises a Stack's Areas count. */
const areaNode = () => ({
  uid: 'area',
  type: 'Area',
  attrs: {},
  metadata: {},
  styles: { default: { classes: [], responsiveStyles: { default: {} } } },
  props: { children: { type: 'slot' as const, slot: 'area-items' } },
  slots: { 'area-items': [] },
});

/**
 * A design prop (added in review). Its value is a CSS value, set per
 * breakpoint in the Settings tab; the prop's name is the CSS property. The
 * component receives a class name, not the value, and puts it on an element.
 */
const textAlign = () => ({
  type: 'choice' as const,
  displayName: 'Text align',
  design: true,
  options: [
    { label: 'Left', value: 'left' },
    { label: 'Center', value: 'center' },
    { label: 'Right', value: 'right' },
  ],
});

